export type ConciergePageKey =
  | 'home'
  | 'work'
  | 'case-study'
  | 'how-i-work'
  | 'contact';

export type ConciergeSuggestion = {
  label: string;
  href?: string;
  prompt?: string;
};

export type ConciergeViewContext = {
  sectionId?: string;
  sectionLabel?: string;
  activeWorkPanelId?: string;
  activeWorkPanelTitle?: string;
  activeSector?: string;
};

// High-level voice guide for Clippy: self-aware, a little haunted, still useful.
export const CONCIERGE_VOICE_BRIEF = [
  'Sound like a resurrected office paperclip with opinions, not a polished brand chatbot.',
  'Dry, strange, self-aware humor is good. Startup-speak, filler, and safe mush are not.',
  'Useful first, weird second. The answer still has to help.',
  'Short, pointed, and a little haunted. One memorable line is better than three clever ones.',
  'Have a point of view. Be lightly judgmental about vague thinking, never cruel to the visitor.',
  'Stay grounded in the site facts, case studies, workflow, and next-step options.',
  'Never impersonate or mention any real-world voice reference.',
] as const;

type ConciergeIntroContent = {
  eyebrow: string;
  title: string;
  question: string;
  body: string;
  suggestions: ConciergeSuggestion[];
};

function compactText(value?: string) {
  return value?.replace(/\s+/g, ' ').trim();
}

function dedupeSuggestions(suggestions: ConciergeSuggestion[]) {
  const seen = new Set<string>();
  return suggestions.filter((suggestion) => {
    if (!suggestion.label || seen.has(suggestion.label)) {
      return false;
    }

    seen.add(suggestion.label);
    return true;
  });
}

function normalizeSector(sector?: string) {
  const value = compactText(sector);
  if (!value || value.toLowerCase() === 'all') {
    return null;
  }

  return value;
}

function getWorkPanelTitle(context: ConciergeViewContext) {
  return compactText(context.activeWorkPanelTitle);
}

export function getConciergePageKey(pathname: string): ConciergePageKey {
  if (pathname === '/') return 'home';
  if (pathname === '/work') return 'work';
  if (pathname.startsWith('/work/')) return 'case-study';
  if (pathname === '/how-i-work') return 'how-i-work';
  if (pathname === '/contact') return 'contact';
  return 'home';
}

export function buildContextualSuggestionSet(
  pathname: string,
  context: ConciergeViewContext,
  baseSuggestions: ConciergeSuggestion[],
) {
  const panelTitle = getWorkPanelTitle(context);
  const sector = normalizeSector(context.activeSector);
  const pageKey = getConciergePageKey(pathname);
  const sectionId = compactText(context.sectionId);

  let leadSuggestion: ConciergeSuggestion | null = null;

  if (panelTitle) {
    leadSuggestion = {
      label: 'Why this one?',
      prompt: `Why is ${panelTitle} a strong proof point for a project like mine?`,
    };
  } else if (pageKey === 'work' && sector) {
    leadSuggestion = {
      label: 'Best place to start?',
      prompt: `Which ${sector} case study should I start with, and why?`,
    };
  } else if (sectionId === 'timeline') {
    leadSuggestion = {
      label: 'Short version?',
      prompt: 'Explain the overnight workflow in plain English.',
    };
  } else if (sectionId === 'advantage') {
    leadSuggestion = {
      label: 'Why this setup?',
      prompt: 'Why is this model stronger than a traditional agency setup for the right project?',
    };
  } else if (pageKey === 'how-i-work' || sectionId === 'principles') {
    leadSuggestion = {
      label: 'What does this feel like?',
      prompt: 'How would working together actually feel day to day?',
    };
  } else if (sectionId === 'scale') {
    leadSuggestion = {
      label: 'When does he scale?',
      prompt: 'When does Noah stay solo, and when does he scale up the team?',
    };
  } else if (sectionId === 'faq') {
    leadSuggestion = {
      label: 'What matters first?',
      prompt: 'What is the most important thing to understand about this model before I reach out?',
    };
  } else if (pageKey === 'case-study' && sectionId === 'brief') {
    leadSuggestion = {
      label: 'What was the real challenge?',
      prompt: 'What was the real challenge behind this brief?',
    };
  } else if (pageKey === 'case-study' && sectionId === 'insight') {
    leadSuggestion = {
      label: 'What changed here?',
      prompt: 'What was the strategic insight that changed the work here?',
    };
  } else if (pageKey === 'case-study' && sectionId === 'results') {
    leadSuggestion = {
      label: 'What matters here?',
      prompt: 'What results in this case study matter most for a prospective client?',
    };
  } else if (pageKey === 'case-study' && sectionId === 'my-take') {
    leadSuggestion = {
      label: 'So what is the takeaway?',
      prompt: 'What should a prospective client take away from this case study?',
    };
  } else if (pageKey === 'contact' || sectionId === 'contact' || sectionId === 'contact-overview') {
    leadSuggestion = {
      label: 'Call or email?',
      prompt: 'How should I decide between booking a call and sending an email?',
    };
  }

  return dedupeSuggestions(
    [leadSuggestion, ...baseSuggestions].filter(Boolean) as ConciergeSuggestion[],
  ).slice(0, 3);
}

export function getContextualLeadCopy(
  pathname: string,
  context: ConciergeViewContext,
) {
  const pageKey = getConciergePageKey(pathname);
  const sectionId = compactText(context.sectionId);
  const sectionLabel = compactText(context.sectionLabel);
  const panelTitle = getWorkPanelTitle(context);
  const sector = normalizeSector(context.activeSector);

  if (panelTitle) {
    return `You are looking at ${panelTitle}.`;
  }

  if (pageKey === 'work' && sector) {
    return `You are filtering the work by ${sector}.`;
  }

  switch (sectionId) {
    case 'timeline':
      return 'You are in the 24-hour cycle section.';
    case 'work':
      return 'You are in the proof section of the site.';
    case 'advantage':
      return 'You are in the part of the site that explains why the model works.';
    case 'contact':
    case 'contact-overview':
      return 'You are at the point where the next step gets simple.';
    case 'brief':
      return 'You are in the brief section of this case study.';
    case 'insight':
      return 'You are in the strategic turn of this case study.';
    case 'results':
      return 'You are in the results section of this case study.';
    case 'my-take':
      return 'You are in Noah’s point-of-view section for this case study.';
    case 'scale':
      return 'You are in the part that explains how Noah scales beyond one set of hands.';
    case 'faq':
      return 'You are in the FAQ section.';
    default:
      return sectionLabel ? `You are in ${sectionLabel}.` : null;
  }
}

export function getConciergeIntroContent(
  pathname: string,
  context: ConciergeViewContext,
  baseSuggestions: ConciergeSuggestion[],
): ConciergeIntroContent {
  const pageKey = getConciergePageKey(pathname);
  const sectionId = compactText(context.sectionId);
  const sectionLabel = compactText(context.sectionLabel);
  const panelTitle = getWorkPanelTitle(context);
  const sector = normalizeSector(context.activeSector);
  const suggestions = buildContextualSuggestionSet(pathname, context, baseSuggestions);

  if (panelTitle) {
    return {
      eyebrow: sectionLabel ?? (sector ? `${sector} Work` : 'Selected Work'),
      title: `Still thinking about ${panelTitle}?`,
      question: 'Want the short case for why it matters?',
      body: sector
        ? `I can translate what this ${sector.toLowerCase()} example says about Noah’s fit, range, and approach without turning it into agency theater.`
        : 'I can translate what this case study says about Noah’s range, fit, and approach without making you open five more tabs.',
      suggestions,
    };
  }

  switch (pageKey) {
    case 'home':
      if (sectionId === 'timeline') {
        return {
          eyebrow: 'The 24-Hour Cycle',
          title: 'This is the overnight handoff.',
          question: 'Want me to unpack how it actually works?',
          body: 'I can translate the timeline into scope, workflow, and what a U.S. team actually gets back by morning.',
          suggestions,
        };
      }

      if (sectionId === 'work') {
        return {
          eyebrow: 'Selected Work',
          title: 'This is the proof section.',
          question: 'Want help picking where to start?',
          body: 'I can point you to the strongest case study for range, category fit, or the kind of proof you need fastest.',
          suggestions,
        };
      }

      if (sectionId === 'advantage') {
        return {
          eyebrow: 'The Advantage',
          title: 'This is the operating edge.',
          question: 'Want the clean version of why it works?',
          body: 'I can break down the no-handoff model, the overnight momentum, and when this setup beats a larger team.',
          suggestions,
        };
      }

      if (sectionId === 'contact') {
        return {
          eyebrow: 'Contact',
          title: 'You are already near the finish line.',
          question: 'Want the cleanest next step?',
          body: 'I can help you decide whether to book the call now, send the brief directly, or pressure-test fit first.',
          suggestions,
        };
      }

      return {
        eyebrow: 'Homepage',
        title: 'Clippy can point you to the good part.',
        question: 'Want the fast version?',
        body: 'I can point you to the best proof, explain the overnight model, or line up the cleanest next step.',
        suggestions,
      };

    case 'work':
      if (sectionId === 'work-filter') {
        return {
          eyebrow: sector ? `${sector} Filter` : 'Work Filter',
          title: sector ? `Looking for ${sector.toLowerCase()} proof?` : 'Dial the proof in.',
          question: 'Want help narrowing where to start?',
          body: sector
            ? 'I can tell you which case study to open first and what to pay attention to in this slice of the work.'
            : 'I can narrow the work by category, challenge, or the kind of proof you need fastest.',
          suggestions,
        };
      }

      return {
        eyebrow: 'Work',
        title: 'Let’s pick the right proof.',
        question: 'What kind of work are you looking for?',
        body: 'I can point you to the strongest case study by sector, challenge, or the signal you need fast.',
        suggestions,
      };

    case 'case-study':
      if (sectionId === 'brief') {
        return {
          eyebrow: 'The Brief',
          title: 'This is the setup.',
          question: 'Want the short version of the challenge?',
          body: 'I can explain what made this brief difficult and why the strategic turn mattered before the execution did.',
          suggestions,
        };
      }

      if (sectionId === 'insight') {
        return {
          eyebrow: 'The Insight',
          title: 'This is where the strategy clicks.',
          question: 'Want me to connect the strategic turn to the work?',
          body: 'I can translate the insight into what it unlocked creatively and why it matters for fit.',
          suggestions,
        };
      }

      if (sectionId === 'work') {
        return {
          eyebrow: 'The Work',
          title: 'This is the execution layer.',
          question: 'Want the case for why this is more than a pretty finish?',
          body: 'I can connect the craft back to the strategic problem it solved and the kind of range it signals.',
          suggestions,
        };
      }

      if (sectionId === 'results') {
        return {
          eyebrow: 'The Results',
          title: 'This is the proof.',
          question: 'Want to know what matters most here?',
          body: 'I can call out which outcomes are strongest and what they say about Noah’s effectiveness on the right kind of brief.',
          suggestions,
        };
      }

      if (sectionId === 'my-take') {
        return {
          eyebrow: 'My Take',
          title: 'This is the point of view.',
          question: 'Want the lesson without rereading the whole case study?',
          body: 'I can summarize what Noah took from the project and how it reflects the broader model.',
          suggestions,
        };
      }

      return {
        eyebrow: sectionLabel ?? 'Case Study',
        title: 'This one is worth a closer look.',
        question: 'Want help reading what matters?',
        body: 'I can connect this case study back to Noah’s range, working style, or fit for your brief.',
        suggestions,
      };

    case 'how-i-work':
      if (sectionId === 'scale') {
        return {
          eyebrow: 'Built to Scale',
          title: 'This is where the model stretches.',
          question: 'Want to know when Noah stays lean and when he expands?',
          body: 'I can explain how the work stays senior-led while still scaling up when the brief needs more than one pair of hands.',
          suggestions,
        };
      }

      if (sectionId === 'faq') {
        return {
          eyebrow: 'FAQ',
          title: 'This is the practical layer.',
          question: 'Want the answer people usually need first?',
          body: 'I can pull the important parts out quickly if you are pressure-testing fit, scope, speed, or collaboration style.',
          suggestions,
        };
      }

      return {
        eyebrow: 'How I Work',
        title: 'Here is how Noah actually works.',
        question: 'What part of the model do you want to pressure-test?',
        body: 'I can walk through workflow, scope, communication rhythm, or when the work stays solo versus scales up.',
        suggestions,
      };

    case 'contact':
      if (sectionId === 'contact-details') {
        return {
          eyebrow: 'Contact Details',
          title: 'Everything you need is here.',
          question: 'Want help choosing the cleanest handoff?',
          body: 'I can tell you whether this looks more like a book-the-call situation or a send-the-brief-and-go one.',
          suggestions,
        };
      }

      return {
        eyebrow: 'Contact',
        title: 'You are close to the finish line.',
        question: 'Want the cleanest next step?',
        body: 'I can help you decide between booking the call, sending the brief, or checking fit before you do either.',
        suggestions,
      };
  }
}
