'use client';

import { useState, useEffect, useRef } from 'react';
import gsap from 'gsap';
import TransitionLink from '@/components/layout/TransitionLink';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import { useLiveClock } from '@/hooks/useLiveClock';
import LogoIcon from '@/components/ui/LogoIcon';
import MagneticButton from '@/components/ui/MagneticButton';

gsap.registerPlugin(ScrollTrigger);
import {
  CAL_COM_URL,
  FOOTER,
  SITE_SETTINGS,
} from '@/lib/content';

function StatusDot({ status }: { status: 'available' | 'focused' | 'offline' }) {
  const colors: Record<typeof status, string> = {
    available: 'bg-accent-secondary',
    focused: 'bg-accent-secondary',
    offline: 'bg-text-tertiary',
  };

  return (
    <span className={`inline-flex size-2 rounded-full ${colors[status]}`} />
  );
}

export default function Footer() {
  const clock = useLiveClock();
  const [copied, setCopied] = useState(false);
  const gridRef = useRef<HTMLDivElement>(null);

  // Entrance animation for footer grid
  useEffect(() => {
    const grid = gridRef.current;
    if (!grid) return;

    const prefersReducedMotion = window.matchMedia(
      '(prefers-reduced-motion: reduce)',
    ).matches;

    const cols = grid.querySelectorAll(':scope > *');
    if (prefersReducedMotion) {
      gsap.set(cols, { opacity: 1, y: 0, scale: 1 });
      return;
    }

    const tween = gsap.fromTo(cols,
      { opacity: 0, y: 40, scale: 0.97, willChange: 'opacity, transform' },
      {
        opacity: 1,
        y: 0,
        scale: 1,
        duration: 0.7,
        stagger: 0.1,
        ease: 'power3.out',
        onComplete: () => { gsap.set(cols, { willChange: 'auto' }); },
        scrollTrigger: {
          trigger: grid,
          start: 'top 90%',
          toggleActions: 'play none none none',
        },
      },
    );

    return () => {
      tween.scrollTrigger?.kill();
      tween.kill();
      gsap.set(cols, { opacity: 1, y: 0, scale: 1 });
    };
  }, []);

  function handleCopyEmail() {
    navigator.clipboard.writeText(FOOTER.email).then(() => {
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }).catch(() => {
      // Fallback: select email text for manual copy
      const input = document.createElement('input');
      input.value = FOOTER.email;
      document.body.appendChild(input);
      input.select();
      document.execCommand('copy');
      document.body.removeChild(input);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    });
  }

  return (
    <footer className="relative border-t border-border-subtle bg-bg-deep">
      {/* Status strip */}
      <div className="flex items-center gap-3 border-b border-border-subtle px-6 py-3 md:px-12">
        <StatusDot status={clock.status} />
        <span className="font-mono text-xs tabular-nums text-text-secondary">
          {clock.bkkTime || '--:--'}
        </span>
        <span className="font-mono text-xs text-text-tertiary">
          Bangkok (GMT+7)
        </span>
      </div>

      {/* Main grid */}
      <div ref={gridRef} className="mx-auto grid max-w-[1200px] grid-cols-1 gap-12 px-6 py-12 md:grid-cols-2 md:px-12 md:py-16">
        {/* Brand block */}
        <div>
          <div className="flex items-center gap-3">
            <LogoIcon />
            <span className="font-mono text-sm font-medium text-text-primary">
              Noah Williams
            </span>
          </div>
          <p className="mt-4 text-sm leading-relaxed text-text-secondary">
            {FOOTER.brandDescription}
          </p>
          <div className="mt-4 flex flex-wrap items-center gap-3">
            <a
              href={`mailto:${FOOTER.email}`}
              className="inline-flex min-h-11 items-center font-mono text-xs text-accent hover:underline"
            >
              {FOOTER.email}
            </a>
            <button
              onClick={handleCopyEmail}
              aria-live="polite"
              className={`rounded border px-3 py-2 font-mono text-xs uppercase tracking-[0.1em] transition-all duration-200 active:scale-[0.97] ${
                copied
                  ? 'border-accent text-accent bg-accent/10'
                  : 'border-border-subtle text-text-tertiary hover:border-accent hover:text-accent'
              }`}
            >
              {copied ? '\u2713 Copied' : 'Copy'}
            </button>
          </div>
        </div>

        {/* Navigation */}
        <div>
          <span className="mb-4 block font-mono text-xs uppercase tracking-[0.2em] text-text-tertiary">
            Navigation
          </span>
          <ul className="flex flex-col gap-1">
            {SITE_SETTINGS.footerNav.map((link) => (
              <li key={link.label}>
                <TransitionLink
                  href={link.href}
                  className="inline-flex min-h-11 items-center text-sm text-text-secondary transition-colors hover:text-text-primary"
                >
                  {link.label}
                </TransitionLink>
              </li>
            ))}
          </ul>
        </div>
      </div>

      {/* Bottom bar */}
      <div className="flex flex-col gap-4 border-t border-border-subtle px-6 py-4 sm:flex-row sm:items-center sm:justify-between md:px-12">
        <div className="flex items-center gap-3">
          <LogoIcon size={18} />
          <span className="font-mono text-xs text-text-tertiary">
            {FOOTER.copyright}
          </span>
        </div>
        <div className="flex items-center gap-6">
          <a
            href={FOOTER.linkedIn}
            target="_blank"
            rel="noopener noreferrer"
            className="inline-block py-3 font-mono text-xs text-text-tertiary transition-colors hover:text-text-primary"
          >
            LinkedIn
          </a>
          <a
            href={CAL_COM_URL}
            target="_blank"
            rel="noopener noreferrer"
            className="inline-block py-3 font-mono text-xs text-text-tertiary transition-colors hover:text-accent active:text-accent/70"
          >
            Book a Call
          </a>
          <MagneticButton>
            <button
              onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })}
              aria-label="Scroll to top"
              className="group flex size-11 items-center justify-center rounded border border-border-subtle text-text-tertiary transition-all hover:border-accent hover:text-accent active:scale-95 active:duration-100"
            >
              <svg
                viewBox="0 0 24 24"
                fill="none"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
                stroke="currentColor"
                className="size-4 transition-transform duration-200 group-hover:animate-[arrowBounce_0.6s_ease-in-out_infinite]"
              >
                <path d="M12 19V5" />
                <path d="M5 12l7-7 7 7" />
              </svg>
            </button>
          </MagneticButton>
        </div>
      </div>
    </footer>
  );
}
